template.solver:
def solve(n):
    pos_size = [0, 0, 0]
    for i in range(1, n + 1):
        pos_size[i % 3] += 1
    val_cnt = [0, 0, 0]
    for v in range(1, n + 1):
        val_cnt[v % 3] += 1
    patterns = [(0,1,2),(0,2,1),(1,0,2),(1,2,0),(2,0,1),(2,1,0),(0,0,0),(1,1,1),(2,2,2)]
    ways = 0
    for p in patterns:
        ok = True
        for r in range(3):
            s = 0
            for j in range(3):
                if p[j] == r:
                    s += pos_size[j]
            if s != val_cnt[r]:
                ok = False
        if ok:
            ways += 1
    res = ways
    for r in range(3):
        res *= factorial(val_cnt[r])
    return res
